import { Slider, Button, Image } from "@nextui-org/react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faPlay, faPause, faRepeat, faForwardStep, faBackwardStep } from "@fortawesome/free-solid-svg-icons";
import { useState, useEffect, useRef } from "react";

const PlayerMusic = ({ URLMusic, setURLMusic, cover, setCover, musicSelected, pistes, setMusicSelected }) => {
    const [isRepeated, setRepeated] = useState(false);
    const [isPaused, setPaused] = useState(false);
    const [duration, setDuration] = useState(0);
    const [currentTime, setCurrentTime] = useState(0);
    const [volume, setVolume] = useState(1)
    const [sliderValue, setSliderValue] = useState(0); // État temporaire pour le slider
    const [isDragging, setIsDragging] = useState(false); // État pour savoir si l'utilisateur manipule le slider

    const audioRef = useRef(null); // Utilisation de useRef pour le lecteur audio


    // Fonction appelée pendant que l'utilisateur déplace le slider
    const handleSliderChange = (value) => {
        setSliderValue(value);
        setIsDragging(true);
    };

    // Fonction appelée lorsque l'utilisateur relâche le slider
    const handleSliderChangeEnd = (value) => {
        const audio = audioRef.current;
        audio.currentTime = value; // Applique la nouvelle position au lecteur audio
        setCurrentTime(value); // Met à jour l'état actuel
        setSliderValue(value); // Assurez-vous que le slider reste à la bonne position
        setIsDragging(false); // L'utilisateur a terminé de manipuler le slider
    };

    // Met à jour le slider lorsque la musique joue, sauf si l'utilisateur est en train de le manipuler
    useEffect(() => {
        const audio = audioRef.current;

        const interval = setInterval(() => {
            if (!isDragging && !audio.paused) {
                setCurrentTime(audio.currentTime);
                setSliderValue(audio.currentTime);
            }
        }, 500); // Mise à jour toutes les 500ms

        return () => clearInterval(interval);
    }, [isDragging]);


    // Met à jour la durée totale et gère le temps actuel
    useEffect(() => {
        const audio = audioRef.current;

        // Vérifie et initialise la durée lorsque l'audio est chargé
        const onLoadedMetadata = () => setDuration(audio.duration || 0);
        // Met à jour le temps actuel à intervalles réguliers
        const interval = setInterval(() => {
            if (!audio.paused) setCurrentTime(audio.currentTime || 0);
            if (audio.currentTime === audio.duration) setPaused(false);
        }, 1000);

        audio.addEventListener("loadedmetadata", onLoadedMetadata);

        return () => {
            clearInterval(interval); // Nettoyage de l'intervalle
            audio.removeEventListener("loadedmetadata", onLoadedMetadata);
        };
    }, []);

    useEffect(() => {
        const audio = audioRef.current;
        if (URLMusic) {
            audio.src = URLMusic;
            setPaused(true);
            audio.play();
        }
    }, [URLMusic]);

    // Formate la durée (minutes:secondes)
    const formatTime = (time) => {
        const minutes = Math.floor(time / 60);
        const seconds = Math.floor(time % 60);
        return `${minutes.toString().padStart(2, "0")}:${seconds.toString().padStart(2, "0")}`;
    };

    // Lecture et pause de la musique
    const togglePlayPause = () => {
        if (Object.keys(musicSelected).length === 0) {
            alert("Aucune musique sélectionnée");
        } else {
            const audio = audioRef.current;
            document.title = audio.title;
            if (isPaused) {
                audio.pause();
            } else {
                audio.play();
            }
            setPaused(!isPaused);
        }
    };

    // Activer/désactiver le mode boucle
    const toggleRepeat = () => {
        const audio = audioRef.current;
        audio.loop = !isRepeated;
        setRepeated(!isRepeated);
    };

    const updateVolume = (value) => {
        const audio = audioRef.current;
        audio.volume = value;
        setVolume(value);
    }

    const nextMusic = () => {
        if (Object.keys(musicSelected).length === 0) {
            alert("Aucune musique sélectionnée");
        } else {
            const indexCurrentMusic = pistes.findIndex((piste) => piste.id === musicSelected.id);
            const piste = indexCurrentMusic === pistes.length - 1 ? pistes[0] : pistes[indexCurrentMusic + 1];

            URLMusic && URL.revokeObjectURL(URLMusic);
            const url = URL.createObjectURL(piste.mp3File);
            const cover = piste.coverUrl ? piste.coverUrl : null;
            document.title = piste.title + " - " + piste.artistName;

            setMusicSelected(piste);
            setCover(cover);
            setURLMusic(url);
        }
    }

    const previousMusic = () => {
        if (Object.keys(musicSelected).length === 0) {
            alert("Aucune musique sélectionnée");
        } else {
            const indexCurrentMusic = pistes.findIndex((piste) => piste.id === musicSelected.id);
            const piste = indexCurrentMusic === 0 ? pistes[pistes.length - 1] : pistes[indexCurrentMusic - 1];

            URLMusic && URL.revokeObjectURL(URLMusic);
            const url = URL.createObjectURL(piste.mp3File);
            const cover = piste.coverUrl ? piste.coverUrl : null;
            document.title = piste.title + " - " + piste.artistName;

            setMusicSelected(piste);
            setCover(cover);
            setURLMusic(url);
        }
    }

    return (
        <div className="flex flex-col w-full shadow z-40">
            {/* Slider */}
            <Slider
                aria-label="Music progress"
                classNames={{
                    track: "bg-default-500/30 rounded-none m-0 cursor-pointer border-none",
                    thumb: "w-2 h-2 after:w-2 after:h-2 after:bg-foreground",
                }}
                color="warning"
                size="sm"
                value={sliderValue} // Affiche la position actuelle ou temporaire
                minValue={0}
                maxValue={duration}
                onChange={handleSliderChange} // Appelé lorsque l'utilisateur déplace le slider
                onChangeEnd={handleSliderChangeEnd} // Appelé lorsque l'utilisateur relâche le slider
            />


            {/* Boutons du lecteur */}
            <div className="flex bg-[#A33634] px-4 py-2" id="playerMusic">
                <div className="grid grid-cols-3 w-full">
                    {/* Affichage informations lecture */}
                    <div className="flex justify-start h-full items-center flex-wrap">
                        {cover ? (
                            <Image
                                src={cover}
                                isBlurred
                                height={84}
                                width={84}
                                radius="md"
                                shadow="sm"
                                className="bg-warning"
                            />
                        ) : (
                            <div className="bg-warning rounded-lg h-[84px] aspect-square flex justify-center items-center text-[32pt] font-semibold">{musicSelected.title && musicSelected.title[0].toUpperCase()}</div>
                        )
                        }
                        <div className="lg:ms-4 text-nowrap flex flex-col">
                            <span className="text-warning-500 font-semibold">{musicSelected.title}</span>
                            {Object.keys(musicSelected).length > 0 ? <span className="text-sm text-warning-500 mb-2">{musicSelected.albumTitle} - {musicSelected.artistName}</span> : ""}
                            {formatTime(currentTime)} / {duration > 0 ? formatTime(duration) : "--:--"}
                        </div>
                    </div>
                    {/* Bouton lecture/pause */}
                    <div className="flex justify-center items-center gap-5">
                        <Button
                            isIconOnly
                            className="rounded-full bg-transparant"
                            disableRipple={false}
                            disableAnimation={true}
                            onClick={previousMusic}
                        >
                            <FontAwesomeIcon icon={faBackwardStep} size="xl" />
                        </Button>
                        <Button
                            isIconOnly
                            className="rounded-full bg-opacity-50"
                            onClick={togglePlayPause}
                            disableRipple={false}
                            disableAnimation={true}
                        >
                            {isPaused ? <FontAwesomeIcon icon={faPause} size="xl" /> : <FontAwesomeIcon icon={faPlay} size="xl" />}
                        </Button>
                        <Button
                            isIconOnly
                            className="rounded-full bg-transparant"
                            disableRipple={false}
                            disableAnimation={true}
                            onClick={nextMusic}
                        >
                            <FontAwesomeIcon icon={faForwardStep} size="xl" />
                        </Button>
                    </div>
                    {/* Bouton boucle */}
                    <div className="flex justify-end items-center">
                        <Button isIconOnly className="bg-transparent" onClick={toggleRepeat}>
                            <FontAwesomeIcon icon={faRepeat}
                                className={isRepeated ? "text-warning" : ""}
                                title={isRepeated ? "Mode boucle" : "Mode simple"}
                                size="xl"
                            />
                        </Button>
                        <Slider
                            size="sm"
                            step={0.05}
                            maxValue={0.7}
                            minValue={0}
                            color="warning"
                            orientation="vertical"
                            aria-label="Volume"
                            value={volume}
                            onChange={updateVolume}
                            classNames={{
                                thumb: "w-2 h-2 after:w-2 after:h-2 after:bg-foreground",
                                track: "border-none"
                            }}
                        />
                    </div>
                </div>
            </div>
            {/* Lecteur audio */}
            <audio
                ref={audioRef}
                src={URLMusic}
                preload="metadata"
                onPause={() => { setPaused(false) }}
                onPlay={() => { setPaused(true) }}
                onEnded={nextMusic}
            />
        </div>
    );
};

export default PlayerMusic;
